/**
 * Every audio filter the bundled ffmpeg has, with every option exactly as ffmpeg reports it: type,
 * range, default, named choices, aliases. Generated by catalog-gen.ts into catalog.json — never edit
 * the JSON by hand; regenerate with `npm run audio -- catalog` when ffmpeg changes.
 *
 * Node-free: the editor UI imports this to draw knobs.
 */
import raw from './catalog.json'

export type OptionType =
  | 'int'            // integer; `choices` = it also accepts the named constants (an enum)
  | 'double' | 'float'
  | 'boolean'
  | 'string'         // free text: expressions, lists, curves (ffmpeg checks it, not us)
  | 'duration'       // seconds as a number, or "[-][HH:]MM:SS[.m...]" / "<n>ms" / "<n>us"
  | 'flags'          // one or more constants joined with '+'
  | 'channel_layout' // "mono", "stereo", "5.1", "FL+FR", …
  | 'sample_fmt'     // "s16", "fltp", …
  | 'rational'       // "num/den" or a number

export interface CatalogOption {
  name: string
  /** other names ffmpeg accepts for the same option (short forms); the plugin always writes `name` */
  aliases: string[]
  type: OptionType
  /** the type as ffmpeg prints it (int64, video_rate, …) */
  ffmpegType: string
  desc: string
  /** ffmpeg's own limits, exactly (INT_MAX, DBL_MAX … resolved to numbers) */
  min?: number
  max?: number
  /** ffmpeg's default as text, e.g. "0.5", "peak", "true", "500" */
  default?: string
  /** named values; for `int` with `choices` they are the enum, for `flags` the flag names */
  constants?: { name: string; value?: number; desc: string; aliases?: string[] }[]
  choices?: boolean
  /** can change while audio plays (ffmpeg "runtime command") — for a future live preview */
  live: boolean
  deprecated: boolean
  /** options inherited from a library section, e.g. aresample's "SWResampler" */
  group?: string
}

export interface Pad { name: string; type: 'audio' | 'video' }

/**
 * effect      – one audio in, one audio out (the usual case)
 * split       – one in, several out (asplit, acrossover, channelsplit …): a step with `outputs` + `merge`
 * multi-input – needs extra inputs (sidechaincompress, afir, amix …): a step with `inputs`, or a `merge`
 * source      – makes audio from nothing (sine, anoisesrc, aevalsrc …): only as a `generate` input
 */
export type FilterRole = 'effect' | 'split' | 'multi-input' | 'source'

export interface CatalogFilter {
  name: string
  description: string
  category: string
  role: FilterRole
  /** ffmpeg's signature, e.g. "A->A", "AA->A", "A->N" */
  signature: string
  inputs: Pad[] | 'dynamic'
  outputs: Pad[] | 'dynamic'
  /** accepts the `enable` timeline expression */
  timeline: boolean
  flags: { timeline: boolean; threads: boolean; commands: boolean }
  options: CatalogOption[]
  /** options the plugin always writes (they'd switch on a video output), e.g. aphasemeter video=false */
  pinned?: Record<string, boolean>
}

export interface Catalog { ffmpeg: string; filters: Record<string, CatalogFilter> }

export const CATALOG = raw as unknown as Catalog

export const filterInfo = (name: string): CatalogFilter | undefined => Object.hasOwn(CATALOG.filters, name) ? CATALOG.filters[name] : undefined

/** Finds an option by its name or any alias. */
export function optionInfo(filter: string, name: string): CatalogOption | undefined {
  return filterInfo(filter)?.options.find((o) => o.name === name || o.aliases.includes(name))
}

/** Category → filter names, in catalog order (for a filter picker). */
export function filtersByCategory(): Record<string, string[]> {
  const out: Record<string, string[]> = {}
  for (const f of Object.values(CATALOG.filters)) (out[f.category] ??= []).push(f.name)
  return out
}

/**
 * How many inputs / outputs a filter with dynamic pads will have for these options, when the rule is
 * known (the common filters). null = depends on things the plugin can't see (e.g. channelsplit on an
 * unknown layout); `checkLook` then confirms against ffmpeg.
 */
export function padCount(filter: string, options: Record<string, unknown>, side: 'in' | 'out'): number | null {
  const f = filterInfo(filter)
  if (!f) return null
  const pads = side === 'in' ? f.inputs : f.outputs
  if (pads !== 'dynamic') return pads.length
  const opt = (k: string, d: number) => { const v = options[k]; return v === undefined ? d : Number(v) }
  const list = (k: string, d: string) => String(options[k] ?? d).trim().split(/[\s|]+/).filter(Boolean).length
  if (side === 'in') {
    switch (filter) {
      case 'amix': case 'amerge': case 'join': case 'astreamselect': return opt('inputs', 2)
      case 'ainterleave': return opt('nb_inputs', opt('n', 2))
      case 'afir': return 1 + opt('nbirs', 1)
      case 'headphone': return null
    }
  } else {
    switch (filter) {
      case 'asplit': case 'aselect': return opt('outputs', filter === 'asplit' ? 2 : 1)
      case 'acrossover': return list('split', '500') + 1
      case 'afir': case 'aiir': case 'anequalizer': case 'ebur128': case 'astreamselect': return 1   // extra outputs are video only
      case 'asegment': { const v = options.timestamps ?? options.samples; return v === undefined ? 1 : list(v === options.timestamps ? 'timestamps' : 'samples', '') + 1 }
    }
  }
  return null
}

/**
 * Filters that do nothing useful — or crash ffmpeg 6.0 — until certain options are set. Found by running
 * every filter at its defaults (`npm run audio -- sweep`). Each inner list: at least one of these must be
 * set. validateLook enforces it; the UI can show `why` on a freshly added step.
 */
export const FILTER_NEEDS: Record<string, { oneOf: string[][]; why: string }> = {
  aeval: { oneOf: [['exprs']], why: 'needs an expression per channel (ffmpeg 6.0 crashes without one)' },
  arnndn: { oneOf: [['model']], why: 'needs a model file (.rnnn) — none ships with the app (ffmpeg 6.0 crashes without one)' },
  asegment: { oneOf: [['timestamps', 'samples']], why: 'needs the points to cut at' },
  asendcmd: { oneOf: [['commands', 'filename']], why: 'needs commands to send' },
  asidedata: { oneOf: [['type']], why: 'needs a side-data type' },
  astreamselect: { oneOf: [['map']], why: 'needs a mapping' },
  channelmap: { oneOf: [['map', 'channel_layout']], why: 'needs a channel map or an output layout' },
  chorus: { oneOf: [['delays'], ['decays'], ['speeds'], ['depths']], why: 'needs delays, decays, speeds and depths (one value per voice)' },
  headphone: { oneOf: [['map']], why: 'needs a channel-to-HRIR map' },
  pan: { oneOf: [['args']], why: 'needs an output layout and channel definitions, e.g. "stereo|c0=c0|c1=c0"' },
}
